\u0022\u0055\u0054\u007a\u003d\u007a\u002f\u005d\u005e\u0026\u0046\u0072\u0059\u0030\u0059\u005e\u004f\u004a\u003a\u0076\u007e\u005b\u006f\u006a\u0022\u005f\u0058\u0061\u0030\u0021\u005e\u0073\u0065\u0067\u0079\u0057\u0033\u007b\u0063\u007d\u0035\u0043\u0045\u004b\u0060\u0065\u0042\u0055\u004d\u002e\u003d\u002b\u0051\u0058\u0058\u003c\u003a\u0078\u007c\u0067\u002b\u0070\u0020\u003a\u003a\u0073\u005d\u0021\u0059\u0022\u006a\u0033\u007c\u006e\u0076\u0076\u0068\u0067\u0053\u007e\u0035\u0035\u0027\u0079\u0068\u002b\u006d\u002a\u005c\u0028\u0073\u006b\u006c\u003e\u0042\u0075\u0044\u0053\u0074\u007d\u002b\u0076\u0028\u0065\u0026\u0042\u003b\u0038\u006f\u0056\u004c\u007b\u0028\u0068\u0057\u002a\u005b\u004e\u0023\u006a\u0023\u0030\u0056\u002b\u004a\u0048\u002d\u002f\u007b\u0048\u0049\u0050\u0030\u0042\u006e\u0056\u006e\u0031\u0067\u004a\u0076\u007a\u0059\u002d\u0058\u005a\u0066\u005d\u0066\u006f\u0049\u0047\u0066\u0048\u0067\u0034\u0035\u0031\u0067\u006b\u0052\u0064\u0045\u005c\u0044\u0053\u0055\u007e\u0067\u0034\u005f\u0074\u003f\u006c\u0027\u007d\u003f\u0067\u004f\u002e\u0032\u0039\u006e\u004f\u0030\u003b\u007c\u004a\u0026\u0055\u0079\u0028\u003d\u007b\u0068\u0062\u0071\u0056\u0064\u003c\u0078\u0039\u0065\u005d\u004e\u004a\u0070\u0048\u0052\u0023\u0042\u007b\u0077\u0031\u0076\u0040\u006e\u002b\u0050\u005b\u006b\u003e\u0060\u0024\u0049\u005c\u002d\u004d\u0061\u002f\u0070\u0022\u0020\u0038\u0070\u005d\u0037\u005e\u003d\u0066\u0022\u0044\u006f\u0036\u0030\u002f\u0060\u0072\u002c\u004b\u0075\u0066\u0045\u002c\u0045\u0031\u006c\u0041\u006d\u004b\u0042\u0039\u0042\u005d\u0060\u0077\u006f\u005e\u0057\u007d\u005d\u0057\u0071\u0037\u006b\u0035\u003f\u0028\u0027\u0069\u0074\u0052\u003a\u004b\u0064\u0055\u0048\u004e\u006d\u0066\u0053\u0056\u0034\u0058\u0069\u0020\u006c\u0053\u0050\u0063\u0050\u0067\u0048\u0031\u0043\u0030\u0044\u003d\u0063\u006f\u002d\u003c\u007c\u0025\u0031\u0069\u0069\u0050\u0040\u0074\u003c\u003a\u0077\u0026\u0023\u0032\u0074\u0023\u0046\u0025\u005d\u0048\u004c\u0047\u002c\u004f\u002b\u007d\u0044\u0032\u0064\u0044\u0069\u0051\u0045\u0053\u0077\u0037\u002d\u0045\u0038\u0049\u0067\u0078\u004f\u0060\u0039\u002a\u006e\u0046\u0039\u0026\u0039\u004a\u0035\u0057\u006c\u0043\u0068\u0071\u0041\u0054\u0078\u0038\u0066\u0062\u005b\u0076\u0060\u0052\u0073\u0078\u0058\u005f\u0078\u002a\u0069\u006b\u004b\u0061\u0036\u005b\u006e\u0037\u0059\u0039\u0050\u0063\u0070\u003e\u0029\u0050\u007c\u0023\u002e\u0027\u0051\u007e\u003e\u0061\u0063\u003e\u005a\u002d\u0034\u0067\u002e\u0070\u006e\u0040\u0052\u006f\u007b\u006d\u0033\u0037\u0076\u0042\u0036\u0065\u0073\u0073\u0061\u0031\u0042\u0053\u0036\u0071\u0072\u0050\u0073\u007a\u002a\u0056\u003c\u006d\u007a\u0033\u0031\u007b\u0078\u0023\u0060\u0046\u005c\u007b\u0051\u004f\u004c\u005b\u006b\u0021\u0066\u004a\u004d\u0071\u002c\u0078\u006c\u002f\u0067\u0066\u0020\u006b\u0070\u0061\u006d\u0053\u0039\u006d\u002e\u007e\u006b\u0024\u0046\u004e\u002e\u0078\u0051\u003b\u0058\u002c\u002b\u0034\u0039\u0051\u005d\u005b\u0040\u0028\u0032\u0024\u004b\u006f\u002a\u0059\u002e\u0061\u0034\u002a\u0038\u0048\u0020\u0027\u0075\u003d\u004a\u0027\u005f\u0060\u0040\u0053\u0052\u0071\u005b\u0031\u006f\u0061\u0041\u0074\u0077\u0062\u0028\u0021\u0072\u0024\u0059\u0032\u007b\u006c\u0054\u0025\u004b\u007d\u0039\u0025\u004c\u003e\u0077\u005f\u0067\u003b\u0022\u0077\u0076\u0035\u0038\u007a\u0077\u004e\u005f\u0041\u0044\u0072\u0028\u007b\u003d\u002b\u0042\u002e\u0079\u0047\u003c\u0038\u0042\u002d\u002e\u0074\u003e\u002d\u005a\u0025\u0072\u0047\u002c\u003f\u007a\u004f\u0066\u0050\u0062\u005f\u003e\u0059\u0059\u0060\u006b\u0046\u002d\u003b\u005f\u004f\u002b\u003c\u007a\u007c\u0074\u0057\u0029\u0047\u007b\u0045\u0036\u0052\u007a\u0029\u002d\u0060\u0068\u0038\u003c\u003b\u006d\u0073\u0063\u006b\u0068\u0046\u004f\u0079\u0079\u0020\u0035\u0065\u006f\u004a\u007a\u005a\u002a\u004e\u0043\u0051\u0068\u0030\u0037\u0072\u006e\u006c\u0041\u0021\u0033\u0075\u0077\u007d\u0037\u0061\u0062\u003f\u0065\u0070\u0030\u0039\u005d\u003e\u006e\u004d\u0037\u006c\u0060\u0058\u0044\u0068\u004a\u0058\u0024\u005c\u002d\u007c\u002f\u0079\u0022\u0035\u0065\u0063\u0030\u006b\u0037\u005f\u006b\u0069\u002c\u0053\u0024\u0079\u0031\u007e\u0052\u0023\u0037\u0030\u0075\u002c\u007a\u0062\u0038\u0025\u005e\u0027\u0052\u005f\u0076\u006e\u006a\u005e\u003b\u0022\u0034\u0034\u0077\u0078\u005b\u0043\u007c\u0032\u0027\u0061\u0076\u0040\u0053\u0052\u006c\u0037\u0035\u005d\u0066\u0066\u003e\u007d\u0041\u0052\u004c\u002f\u0064\u005c\u0048\u0066\u007e\u0032\u0038\u0036\u0042\u0023\u0078\u004c\u0052\u0030\u0063\u0027\u0062\u003b\u0046\u0064\u0029\u005e\u0064\u004b\u0066\u0027\u003d\u0059\u002d\u0046\u0048\u003c\u007c\u0037\u005f\u007c\u003d\u0071\u003b\u0078\u0029\u0069\u005d\u004d\u0076\u0021\u0043\u007e\u0059\u0075\u003a\u0028\u006a\u006d\u002b\u0049\u0042\u004e\u0043\u0065\u0070\u0035\u005b\u004b\u0051\u007e\u003b\u0038\u0046\u0036\u0039\u0056\u0047\u0020\u0020\u0031\u0073\u002f\u006d\u0045\u0025\u003f\u004d\u0033\u0030\u004c\u0026\u003d\u0033\u0049\u002d\u005f\u005a\u004f\u0031\u006b\u0024\u0031\u0064\u005e\u007b\u003a\u002e\u0041\u0060\u0042\u002e\u004b\u0040\u003f\u0059\u007e\u0046\u0058\u0049\u0062\u0059\u004a\u004e\u005a\u0044\u0070\u003d\u003b\u0052\u0058\u0056\u0079\u0047\u0028\u0054\u0021\u0050\u0061\u0078\u006f\u004f\u0033\u0023\u0068\u0035\u0048\u007d\u007b\u0034\u005a\u003b\u0046\u006d\u0026\u0060\u0077\u0023\u0043\u0040\u0071\u003c\u005b\u005c\u0048\u0040\u002f\u007d\u0034\u003b\u0064\u0066\u0063\u0062\u0042\u0072\u005b\u0037\u0023\u006e\u006a\u0033\u004c\u003b\u0062\u004c\u0037\u003d\u0073\u007e\u007a\u004d\u002b\u005a\u007c\u0059\u0051\u002d\u0044\u003e\u0068\u0022\u004a\u005f\u0059\u0031\u007e\u0069\u004d\u0045\u0029\u0062\u0031\u007b\u006e\u0026\u007b\u0040\u0065\u0066\u0053\u0058\u0036\u0021\u0031\u006b\u0034\u0059\u002b\u0066\u0063\u0056\u004e\u006d\u0034\u0065\u0075\u0032\u007d\u0031\u0037\u0024\u0058\u0023\u0066\u0059\u0026\u0056\u005a\u006e\u0061\u0030\u0070\u0039\u0022\u006e\u0023\u0026\u0062\u006d\u002d\u0066\u0066\u0035\u0037\u0060\u007d\u0068\u002b\u0045\u0058\u0050\u005e\u0069\u0076\u005f\u002a\u0029\u007e\u006f\u005d\u006d\u0073\u002a\u0034\u0038\u005a\u0043\u005d\u002e\u005d\u0064\u004e\u005f\u002f\u0022\u004a\u003a\u0078\u0041\u007d\u0032\u0027\u0050\u0020\u005f\u002a\u0028\u004e\u0064\u0030\u005e\u005b\u0049\u002b\u0034\u0054\u0031\u0071\u0077\u0072\u002b\u004b\u0025\u0028\u0035\u0062\u0022\u0041\u006c\u007b\u0044\u007e\u0039\u006c\u0031\u006f\u0041\u0030\u007e\u0074\u0078\u0059\u003a\u0053\u0032\u0053\u0062\u0052\u0079\u003c\u0058\u006a\u0078\u005e\u0052\u006f\u0039\u005e\u0035\u004f\u003b\u0066\u005f\u0075\u0072\u0046\u002a\u006e\u0020\u0032\u004f\u004d\u0031\u0024\u002d\u0069\u0034\u0072\u0035\u004e\u0051\u0045\u0053\u0026\u0031\u0037\u0035\u0062\u002d\u005f\u0027\u0023\u0026\u0076\u003c\u0072\u0046\u0024\u007d\u0027\u004a\u0034\u0056\u0074\u0041\u0044\u007c\u005a\u0042\u007b\u003d\u005c\u0064\u0052\u0077\u003a\u0033\u0040\u0020\u0020\u0067\u0051\u0032\u004d\u002d\u002b\u0023\u005e\u004f\u0034\u0031\u0050\u003c\u0041\u0043\u0020\u0024\u0075\u0030\u0074\u005b\u0048\u0045\u0061\u0041\u0063\u0050\u0040\u0058\u0045\u0037\u0021\u003f\u006c\u0073\u0056\u0054\u0022\u004e\u0051\u0062\u0043\u0037\u006a\u0071\u0056\u002b\u0061\u0076\u0062\u0026\u0077\u0045\u003f\u002d\u007e\u003f\u007e\u0039\u007b\u0057\u003f\u007a\u003f\u0066\u005b\u0035\u0053\u0062\u0029\u0059\u0069\u0061\u0023\u003b\u0043\u0036\u006e\u006a\u0031\u002a\u0053\u0033\u005e\u006e\u0045\u0041\u006e\u0023\u0051\u0022\u0033\u0051\u0041\u006b\u0067\u0034\u0023\u0057\u0027\u0049\u004e\u005d\u0026\u005d\u0069\u0069\u002c\u002a\u0054\u0055\u004f\u002f\u005c\u0046\u003b\u0048\u0056\u0071\u007c\u007d\u005a\u0027\u004a\u0062\u002c\u0032\u0052\u0079\u0066\u0040\u004e\u0052\u0029\u006b\u0072\u0049\u0054\u0071\u004b\u0052\u003f\u0054\u0026\u002f\u0068\u005f\u002b\u0029\u0026\u004b\u0029\u0075\u0068\u0072\u005f\u0053\u0058\u007b\u0049\u0050\u0037\u0039\u0051\u0029\u0065\u0049\u006b\u0056\u0029\u0051\u0068\u003a\u0022\u002e\u0040\u0030\u0074\u0060\u0022\u0048\u0033\u0077\u0074\u0032\u0073\u003b\u0078\u0063\u0020\u006c\u0028\u002f\u0069\u0033\u007b\u005f\u006a\u006d\u0075\u0050\u006c\u0049\u007d\u0044\u0072\u0028\u0052\u0037\u0033\u003e\u0054\u003d\u0061\u0026\u0032\u007e\u0045\u0068\u0067\u0051\u0033\u0053\u003c\u0031\u004b\u0034\u007e\u0020\u0071\u003c\u0053\u007c\u0078\u0052\u002e\u0057\u004a\u007b\u0043\u0050\u007a\u005c\u0075\u006e\u004d\u0048\u0075\u0038\u0066\u004c\u006b\u006b\u0041\u0021\u0066\u0049\u0071\u0023\u0069\u0024\u006a\u0029\u002c\u0063\u0044\u0022\u0077\u0052\u0027\u006f\u0029\u0050\u0023\u0063\u0027\u0076\u0035\u005f\u0030\u005a\u0036\u0051\u0062\u005c\u0058\u006b\u0047\u0039\u0078\u006c\u0025\u005e\u0050\u0054\u002e\u007b\u0044\u0063\u0047\u004b\u0024\u003b\u0045\u0072\u0062\u004e\u0031\u005e\u0054\u0024\u0026\u0037\u0046\u0056\u0057\u006e\u0029\u0050\u0022\u0078\u0030\u0067\u002a\u0072\u006f\u0039\u005f\u0072\u0042\u0024\u007e\u0030\u006f\u0060\u005a\u0046\u002b\u0067\u004a\u007c\u004b\u0025\u0051\u007b\u006d\u0030\u003f\u002a\u0053\u0037\u0042\u0031\u0035\u003f\u0058\u0040\u0030\u007b\u0051\u006f\u0023\u005c\u0037\u0043\u007d\u0043\u0030\u003e\u006c\u0061\u0034\u0034\u0064\u004f\u0078\u0069\u0032\u0026\u0048\u0075\u0064\u0061\u002e\u005f\u006a\u006b\u0078\u003b\u002d\u0069\u0066\u0076\u006b\u003b\u0054\u0026\u004f\u0056\u0067\u0067\u005f\u0049\u0046\u006b\u0051\u003c\u0029\u0045\u0045\u006d\u0069\u003a\u006d\u0023\u0028\u005b\u0025\u0044\u0050\u004a\u005e\u0070\u005f\u0069\u0054\u005b\u0044\u0078\u0054\u004c\u006b\u0024\u004e\u002e\u0024\u0043\u005c\u0047\u0039\u0043\u0035\u0056\u0063\u002e\u0030\u0075\u002b\u004d\u0043\u0056\u004e\u005a\u004c\u0072\u0039\u0068\u0036\u0025\u0062\u006f\u0030\u005a\u003a\u004a\u0039\u005f\u002a\u003d\u0072\u007c\u007c\u006f\u0050\u0026\u002c\u003c\u002a\u0044\u003a\u003d\u0072\u0033\u0074\u0064\u005b\u0057\u006b\u0056\u0028\u003e\u003e\u0022\u004e\u007b\u002c\u006f\u0068\u005a\u0075\u0055\u0049\u006b\u0026\u0047\u0025\u0029\u005b\u0055\u0050\u0035\u005a\u0037\u0032\u0075\u0020\u007e\u004b\u0041\u0029\u0072\u003f\u0072\u002f\u0070\u006f\u0078\u007c\u0069\u003f\u0056\u0060\u0028\u005a\u0052\u0072\u0054\u0025\u0032\u0070\u0073\u0074\u0067\u0039\u0071\u002e\u006e\u004d\u0077\u0068\u007e\u0050\u007a\u003f\u0022\u0030\u0062\u0061\u0047\u0043\u0060\u0031\u0037\u004c\u0056\u0069\u0071\u005c\u0036\u005e\u0077\u0051\u006a\u0067\u006c\u003d\u0044\u0076\u006a\u0059\u0035\u0038\u006f\u0058\u007a\u003d\u0048\u004d\u0056\u004e\u0033\u004f\u005b\u0037\u004c\u0074\u0027\u005d\u0022\u0047\u007b\u0074\u005d\u005c\u004c\u004d\u0075\u0044\u0054\u0044\u0055\u0065\u0065\u0068\u003d\u0045\u004c\u003b\u004e\u003f\u0074\u002b\u0035\u005e\u0020\u0069\u0076\u0073\u005f\u0069\u003a\u006a\u007c\u0065\u006b\u004f\u0072\u0034\u0051\u002b\u0060\u0072\u0026\u0034\u0033\u0043\u003c\u0066\u0032\u003b\u0020\u0055\u005b\u0076\u0040\u0060\u0051\u0071\u0022\u0070\u0033\u0062\u0032\u0074\u006e\u0064\u0032\u003a\u0072\u0032\u0034\u003b\u003c\u0061\u0038\u0075\u003a\u003c\u0060\u0073\u0044\u0038\u0044\u0035\u0050\u007e\u0044\u007d\u0021\u004d\u0044\u0031\u0064\u004e\u0041\u0025\u0078\u0076\u0060\u006b\u004d\u005c\u0023\u0072\u0055\u0046\u003d\u002e\u006a\u004b\u007c\u0046\u004a\u0024\u005c\u0033\u0061\u0029\u0076\u0078\u007e\u006a\u0062\u0064\u0065\u0048\u0070\u0067\u0071\u002b\u0041\u004b\u003a\u007d\u0077\u004a\u0052\u0022\u006c\u004e\u004a\u0074\u0046\u002e\u0066\u0033\u0033\u0039\u0049\u007d\u0047\u007b\u0026\u0061\u0049\u0036\u004d\u005b\u0027\u005c\u0046\u005c\u0042\u0058\u0068\u007c\u0044\u0075\u0027\u0072\u0048\u0029\u007b\u0036\u0024\u0076\u0063\u0073\u0032\u0060\u005c\u007b\u003d\u0049\u0048\u003c\u0051\u005a\u002d\u0047\u0051\u0053\u0066\u0028\u0074\u003e\u0032\u0059\u005e\u0073\u0021\u0041\u0078\u0046\u004e\u007e\u0045\u0078\u0032\u0049\u005f\u006a\u0052\u005f\u0071\u0057\u003f\u0065\u0032\u0060\u0061\u0023\u0050\u006a\u002c\u0058\u0050\u003d\u006d\u0061\u004a\u004c\u0031\u0044\u0025\u006f\u0041\u002a\u0073\u0034\u0028\u0073